// @ts-nocheck
export const code = async (inputs) => {
  const C = {
    "app_url": "{{trigger['body']['app_url']}}",
    "inbound_token": "{{trigger['body']['inbound_token']}}",
    "company_name": "{{trigger['body']['company_name']}}",
    "flow": "ADMISSION_CALL",
    "brand_tone": "formal, precise, courteous",
    "brand_signature": "",
    "followup_days": [
      2,
      5,
      10
    ],
    "quote_validity_days": 30,
    "same_day_quote_hours": 8,
    "default_owner": "",
    "own_domain": "",
    "quote_series": "SMT/Q",
    "catalogue": [],
    "options": [],
    "owners": [],
    "counsellors_from": "team",
    "voice_language": "hi"
  };
  // v5.1: the app sends app_url, inbound_token and company_name with every call (the step's inputs, from the trigger body)
  C.app_url = String(inputs.app_url || '').replace(/\/+$/, ''); C.inbound_token = String(inputs.inbound_token || ''); C.company_name = String(inputs.company_name || '');
  if (!C.brand_signature) C.brand_signature = 'For ' + C.company_name;
  C.today = new Date().toISOString(); C.year = new Date().getFullYear();
  C.catalogue_text = C.catalogue.map(c => c.code + ' = ' + c.name + (c.product_line ? ' (' + c.product_line + ')' : '')).join('; ');
  C.options_for_model = (C.options || []).filter(o => o.model === ((inputs.body || {}).Model_Code || '')).map(o => o.code + ' = ' + o.description).join('; ');
  return C;
};

// @ts-nocheck
export const code = async (inputs) => {
  let parsed = {"grade": 0, "score": 0, "summary": "", "next_action": ""};
  function cdmNum(s, integer) { const t = String(s).replace(/₹|\b(?:rs\.?|inr)(?![a-z])/gi, ' ').trim(); if (/0x[0-9a-f]/i.test(t) || /\d\s*e\s*[+-]?\d/i.test(t) || /\d\.\d{3},\d/.test(t) || /\d\.\d+\.\d/.test(t)) return null; const m = t.match(/-?\d[\d,]*(\.\d+)?/); if (!m) return null; let x = Number(m[0].replace(/,/g, '')); if (!isFinite(x)) return null; const u = t.slice(m.index + m[0].length).trim().toLowerCase().match(/^(thousand|k|lakhs?|lacs?|l|crores?|cr|million|mn)(?![a-z])/); if (u) x = x * (/^(thousand|k)$/.test(u[1]) ? 1e3 : /^(million|mn)$/.test(u[1]) ? 1e6 : /^(lakhs?|lacs?|l)$/.test(u[1]) ? 1e5 : 1e7); x = parseFloat(x.toPrecision(15)); return integer && !Number.isInteger(x) ? null : x; }
  function cdmBool(s) { const t = String(s).trim().toLowerCase().replace(/[.!?।]+$/, ''); if (['yes', 'y', 'true', '1', 'haan', 'हाँ', 'हां', 'હા'].includes(t)) return true; if (['no', 'n', 'false', '0', 'nahi', 'नहीं', 'ना', 'ના'].includes(t)) return false; return null; }
  function cdmChoice(s, ch) { const t = String(s).trim().toLowerCase(); const L = ch.map((c) => [c, String(c).toLowerCase()]); const exact = L.find((x) => x[1] === t); if (exact) return exact[0]; const esc = (x) => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); const inSpan = L.filter((x) => new RegExp('(^|[^a-z0-9])' + esc(x[1]) + '([^a-z0-9]|$)').test(t)).sort((a, b) => b[1].length - a[1].length); if (inSpan.length) return inSpan[0][0]; const inChoice = t.length >= 2 ? L.find((x) => x[1].includes(t)) : null; return inChoice ? inChoice[0] : null; }
  function cdmFields(fields, decl, conf, choices) { if (typeof fields === 'string') { try { fields = JSON.parse(fields); } catch (e) { fields = null; } } const ents = fields && Array.isArray(fields.entities) ? fields.entities : null; const keys = Object.keys(decl); const out = Object.create(null); for (const k of keys) out[k] = null; if (!ents) { out._parse_error = 'true'; if (conf) out[conf] = 0; out.fields_found = 0; out.fields_total = keys.length; return out; } const best = Object.create(null); for (const e of ents) { if (!e || !Object.prototype.hasOwnProperty.call(decl, e.type) || e.text === undefined || e.text === null || String(e.text).trim() === '') continue; const c = Number(e.confidence) || 0; if (!best[e.type] || c > best[e.type].c) best[e.type] = { v: String(e.text).trim(), c }; } const cs = []; for (const k of keys) { const b = best[k]; if (!b) continue; const t = decl[k]; const ch = choices && Array.isArray(choices[k]) && choices[k].length ? choices[k] : null; const v = (t === 'integer' || t === 'number') ? cdmNum(b.v, t === 'integer') : t === 'boolean' ? cdmBool(b.v) : ch ? cdmChoice(b.v, ch) : b.v; if (v === null) continue; out[k] = v; cs.push(b.c); } if (conf) out[conf] = cs.length ? Math.min(...cs) : 0; out.fields_found = cs.length; out.fields_total = keys.length; return out; }
  { const got = cdmFields(inputs.ai_fields, {"grade": "string", "score": "number", "summary": "string", "next_action": "string"}, null, {"grade": ["HOT", "WARM", "COLD"]}); for (const [k, v] of Object.entries(got)) if (v !== null) parsed[k] = v; }   // Pucho CDM extract → one value per field
  const JEVP = {}; for (const k of Object.keys(inputs)) if (k.indexOf('jev_') === 0 && k.slice(-11) !== '_confidence') { const f = k.slice(4), v = inputs[k], conf = Number(inputs[k + '_confidence']); const pol = JEVP[f] || [0.5, null]; if (v !== undefined && v !== '' && (isNaN(conf) || conf >= pol[0])) parsed[f] = v; else if (pol[1] !== null && pol[1] !== undefined) parsed[f] = pol[1]; } /* a Jev answer lands only when confident; else the fallback */
  const build = async (inputs) => {
  const C = inputs.C, p = inputs.b || {}, r = parsed || {};
  const allowed = ["Lead_ID", "Created_At", "Name", "Phone", "Email", "Course", "Source", "Notes", "Stage", "Grade", "Score", "AI_Summary", "Next_Action", "Call_Status", "Last_Called_At", "Transcript", "Assigned_To", "Next_Followup_At", "Lost_Reason"]; const fills = {"Stage": "Called", "Grade": "WARM", "Score": 62, "Call_Status": "Completed", "AI_Summary": "Simulated call — interested, wants the fee plan and a demo class.", "Next_Action": "Share the fee plan and book a demo", "Last_Called_At": "now"};
  const title = (s) => s.replace(/(^|_)(\w)/g, (m, a, b) => a + b.toUpperCase());
  const row = {}; for (const k of allowed) { if (p[k] !== undefined) row[k] = p[k]; else if (r[k] !== undefined) row[k] = r[k]; else if (r[k.toLowerCase()] !== undefined) row[k] = r[k.toLowerCase()]; }
  for (const k of Object.keys(r)) { const t = title(k); if (allowed.includes(t) && row[t] === undefined) row[t] = Array.isArray(r[k]) ? r[k].join('; ') : r[k]; }
  for (const [k, v] of Object.entries(fills)) row[k] = v === 'now' ? new Date().toISOString() : v;
  row['Lead_ID'] = '';   // the app numbers it
  row['Created_At'] = row['Created_At'] || new Date().toISOString();
  for (const k of allowed) if (row[k] === undefined) row[k] = '';
  return { row };
};
  const out = await build(inputs);
  return { ...out, result: parsed };
};

